kernel_enforcement_nftables.raw_nft_output_isolated:
table inet minifw {
	set minifw_block_v4 {
		type ipv4_addr
		timeout 1h
		elements = { 10.10.0.20 timeout 15s expires 14s972ms }
	}

	chain forward {
		type filter hook forward priority filter; policy accept;
		ct state new counter packets 0 bytes 0 comment "MiniFW-AI-Conntrack"
		ip saddr @minifw_block_v4 counter packets 0 bytes 0 drop comment "MiniFW-AI-Blocklist"
	}
}

kernel_enforcement_nftables.raw_nft_output_after_expiry:
table inet minifw {
	set minifw_block_v4 {
		type ipv4_addr
		timeout 1h
	}

	chain forward {
		type filter hook forward priority filter; policy accept;
		ct state new counter packets 0 bytes 0 comment "MiniFW-AI-Conntrack"
		ip saddr @minifw_block_v4 counter packets 0 bytes 0 drop comment "MiniFW-AI-Blocklist"
	}
}
